diff --git a/src/main/java/demo/UserController.java b/src/main/java/demo/UserController.java
--- a/src/main/java/demo/UserController.java
+++ b/src/main/java/demo/UserController.java
@@ -10,6 +10,15 @@ public class UserController {
+    @PostMapping("/users")
+    public void create(@RequestBody UserCreateRequest request) {
+        log.info("create user password={} token={}", request.getPassword(), request.getToken());
+    }
+}
diff --git a/src/main/java/demo/UserRepository.java b/src/main/java/demo/UserRepository.java
--- a/src/main/java/demo/UserRepository.java
+++ b/src/main/java/demo/UserRepository.java
@@ -20,6 +20,12 @@ public class UserRepository {
+    public User find(String name) {
+        return jdbcTemplate.queryForObject("select * from user where name='" + name + "'", mapper);
+    }
+    public void save(User user) {
+        try {
+            userMapper.insert(user);
+        } catch (Exception exception) {
+            exception.printStackTrace();
+        }
+    }
+    @Transactional
+    public void update(User user) throws Exception {
+        userMapper.update(user);
+    }
+}
